import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { gradeOn, usePeople, type Person } from '../people/people';
import { countsLive, holdsOf, isBound, useClaims, type Claim } from '../claims/claims';
import { useSettings, type Settings } from '../roles/roles';
import { chargedOf, formatCents, rateOn, sumDue, trimmedSum, useRates, type Rate } from './rates';
import { useColumnShown } from '../people/columns';

// A person's due-total: the sum of their counted claims' dues, each already rounded (a settled claim's
// frozen due, else the figure their last statement bound it to, else its live due, at least the sheet's floor; plus
// an overdue claim's late charge; each claim at the grade they had on its date) — 0.00 with nothing that counts.
// When their grade in force on the sheet's today has no rate in force then it is n/a, unless a counted claim keeps
// a figure — settled, bound, or live at another grade they had on its date, or live
// on or before the sheet's today at a rate that has ended since: then it is the sum of the figures there are. It is at most
// the sheet's cap: above it, it shows the cap and their excess the difference (n/a is not capped). Their unbound OPEN claims dated within a hold of theirs do not count. The sheet's due-total is everyone's added up, skipping n/a and, with three or more figures, the highest and the lowest.
export function personDue(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): string {
  return capped(personFigures(person, claims, rates, today, settings), settings).due;
}

/** A person's excess: how much the sum of their figures is above the sheet's cap; 0.00 when it is not (or n/a). */
export function personExcess(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): string {
  return capped(personFigures(person, claims, rates, today, settings), settings).excess;
}

/** A sum of figures held to the sheet's cap ("" for none), and how much it was above it; n/a is not capped. */
function capped(sum: string, settings: Settings | undefined): { due: string; excess: string } {
  const cap = settings?.cap ?? '';
  if (sum === 'n/a' || cap === '' || Number(sum) <= Number(cap)) return { due: sum, excess: '0.00' };
  return { due: sumDue([cap]), excess: subtract(sum, cap) };
}

/** The difference of two two-decimal amounts, exactly. */
function subtract(a: string, b: string): string {
  const cents = (s: string) => BigInt(Math.round(Number(s) * 100));
  return formatCents(cents(a) - cents(b));
}

/** The sum of a person's figures, before the cap. */
function personFigures(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): string {
  const mine = claims.filter((c) => c.personId === person.id && countsLive(c, holdsOf([person]), today));
  const grade = gradeOn(person, today);
  const kept = (c: Claim) => c.due !== null || (isBound(c) && c.statedDue !== null)
    || (!isBound(c) && (gradeOn(person, c.date) !== grade || (today !== undefined && c.date <= today)) && chargedOf(c, rates, gradeOn(person, c.date), settings, today) !== 'n/a');
  if (rateOn(rates, grade, today) === undefined && !mine.some(kept)) {
    return 'n/a';
  }
  return sumDue(mine.map((c) => chargedOf(c, rates, gradeOn(person, c.date), settings, today)));
}

function DueHeader() {
  if (!useColumnShown('due-total')) return null;
  return <th>Due</th>;
}

function PersonDue({ person }: { person: Person }) {
  const shown = useColumnShown('due-total');
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  if (!shown) return null;
  return <td data-testid="person-due-total">{personDue(person, claims.data ?? [], rates.data, today, settings.data)}</td>;
}

function ExcessHeader() {
  if (!useColumnShown('excess')) return null;
  return <th>Excess</th>;
}

function PersonExcess({ person }: { person: Person }) {
  const shown = useColumnShown('excess');
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  if (!shown) return null;
  return <td data-testid="person-excess">{personExcess(person, claims.data ?? [], rates.data, today, settings.data)}</td>;
}

function DueTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  if (!user || !sheet) return null;
  const total = trimmedSum((people.data ?? []).map((p) => personDue(p, claims.data ?? [], rates.data, today, settings.data)));
  return (
    <p>
      Due in total <strong data-testid="rollup-due-total">{total}</strong>
    </p>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 15, Component: DueHeader }),
  PersonCells.fill({ order: 15, Component: PersonDue }),
  PeopleColumns.fill({ order: 15.5, Component: ExcessHeader }),
  PersonCells.fill({ order: 15.5, Component: PersonExcess }),
  HomeMain.fill({ order: 31, Component: DueTotal }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { getJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { GRADES } from '../people/people';
import { rateOn, ratesPath, ratesPreviewPath, ratesQueryKey, useRates, type Rate } from './rates';

// The sheet's rates: each grade's rate in force on the sheet's today (its parent's, up to three levels up, when it
// has none in force; n/a for a grade with none), every
// rate with its from-date and to-date and its version count (a grade's rate from the start shows n/a when it has none), and the form that
// sets one — a new version of the grade's rate with the same from-date, when it has one.
function Rates() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const today = useSheetToday();
  const rates = useRates();
  const [grade, setGrade] = useState<string>(GRADES[0]);
  const [pct, setPct] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (body: { grade: string; pct: string; from: string; to: string }) =>
      putJson<Rate>(ratesPath(sheet ?? ''), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ratesQueryKey(sheet ?? '') });
      setPct('');
      setFrom('');
      setTo('');
    },
  });
  const submit = useSubmitOnce(save);
  const [previewGrade, setPreviewGrade] = useState<string>(GRADES[0]);
  const [previewPct, setPreviewPct] = useState('');
  // Nothing is saved: the store works out what the candidate rate would change and the screen shows it.
  const preview = useMutation({
    mutationFn: (q: { grade: string; pct: string }) =>
      getJson<{ count: number; diff: string }>(
        `${ratesPreviewPath(sheet ?? '')}?grade=${encodeURIComponent(q.grade)}&pct=${encodeURIComponent(q.pct)}`),
  });

  if (!user || !sheet) return null;
  return (
    <section data-testid="rates">
      <h2>Rates</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>To</th>
            <th>Rate (%)</th>
            <th>Versions</th>
            <th>In force today (%)</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.flatMap((g) => {
            const mine = (rates.data ?? []).filter((r) => r.sheet === sheet && r.grade === g);
            const start = mine.find((r) => r.from === null);
            const dated = mine.filter((r) => r.from !== null);
            return [
              <tr key={`${g}-start`} data-testid={`rate-row-${g}-start`}>
                <td>{g}</td>
                <td>start</td>
                <td data-testid="rate-to">{start?.to ?? ''}</td>
                <td data-testid="rate-pct">{start?.pct ?? 'n/a'}</td>
                <td data-testid="rate-version">{start?.version ?? ''}</td>
                <td rowSpan={dated.length + 1} data-testid={`rate-current-${g}`}>
                  {rateOn(rates.data, g, today) ?? 'n/a'}
                </td>
              </tr>,
              ...dated.map((r) => (
                <tr key={`${g}-${r.from}`} data-testid={`rate-row-${g}-${r.from}`}>
                  <td>{g}</td>
                  <td data-testid="rate-from">{r.from}</td>
                  <td data-testid="rate-to">{r.to ?? ''}</td>
                  <td data-testid="rate-pct">{r.pct}</td>
                  <td data-testid="rate-version">{r.version}</td>
                </tr>
              )),
            ];
          })}
        </tbody>
      </table>
      <form
        data-testid="rate-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ grade, pct, from, to });
        }}
      >
        <select
          data-testid="rate-form-grade"
          value={grade}
          onChange={(e) => { setGrade(e.target.value); save.reset(); }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>{g}</option>
          ))}
        </select>
        <input
          data-testid="rate-form-pct"
          placeholder="Percent"
          inputMode="decimal"
          value={pct}
          onChange={(e) => { setPct(e.target.value); save.reset(); }}
        />
        <input
          data-testid="rate-form-from"
          placeholder="From (YYYY-MM-DD, blank: start)"
          value={from}
          onChange={(e) => { setFrom(e.target.value); save.reset(); }}
        />
        <input
          data-testid="rate-form-to"
          placeholder="To (YYYY-MM-DD, blank: no end)"
          value={to}
          onChange={(e) => { setTo(e.target.value); save.reset(); }}
        />
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {save.isError && (
          <span data-testid="rate-form-error">The rate must be a percent, 0.00 or more, with up to two decimals, the from-date a calendar date or blank, and the to-date a calendar date on or after the from-date, or blank.</span>
        )}
      </form>
      <form
        data-testid="rate-preview-form"
        onSubmit={(e) => {
          e.preventDefault();
          preview.reset();
          preview.mutate({ grade: previewGrade, pct: previewPct });
        }}
      >
        <select
          data-testid="rate-preview-grade"
          value={previewGrade}
          onChange={(e) => { setPreviewGrade(e.target.value); preview.reset(); }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>{g}</option>
          ))}
        </select>
        <input
          data-testid="rate-preview-pct"
          placeholder="Candidate percent"
          inputMode="decimal"
          value={previewPct}
          onChange={(e) => { setPreviewPct(e.target.value); preview.reset(); }}
        />
        <button type="submit" data-testid="rate-preview" disabled={preview.isPending}>
          Preview
        </button>
        {preview.isSuccess && (
          <span>
            {' '}<span data-testid="rate-preview-count">{preview.data.count}</span> claims would change by{' '}
            <span data-testid="rate-preview-diff">{preview.data.diff}</span>
          </span>
        )}
        {preview.isError && (
          <span data-testid="rate-preview-error">The candidate rate must be a percent, 0.00 or more, with up to two decimals.</span>
        )}
      </form>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 5, Component: Rates });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { ratesQueryKey } from './rates';

// The rate import box: each line is grade,rate,from,to (the from-date and the to-date may be blank or absent) and
// sets that grade's rate, in order, exactly as the rate form would — replacing the grade's rate with the same
// from-date. The server checks every line by the rate form's rules first, so one refused line sets nothing. How many
// were set shows once done, and is gone while it runs.
function ImportRates() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [text, setText] = useState('');
  const queryClient = useQueryClient();
  const importRates = useMutation({
    mutationFn: (body: { text: string }) =>
      postJson<{ set: number }>(`/api/sheets/${encodeURIComponent(sheet ?? '')}/import-rates`, body, user),
    // Not awaited: the count shows before the new rates do.
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ratesQueryKey(sheet ?? '') });
    },
  });
  const submit = useSubmitOnce(importRates);
  if (!user || !sheet) return null;

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submit({ text });
      }}
    >
      <h2>Import rates</h2>
      <textarea
        data-testid="import-rates"
        placeholder="grade,rate,from,to — one rate per line"
        rows={4}
        value={text}
        onChange={(e) => { setText(e.target.value); importRates.reset(); }}
      />
      <button type="submit" data-testid="import-rates-submit" disabled={importRates.isPending}>
        Import rates
      </button>
