            <span data-testid="rate-preview-diff">{preview.data.diff}</span>
          </span>
        )}
        {preview.isError && (
          <span data-testid="rate-preview-error">The candidate rate must be a percent, 0.00 or more, with up to two decimals.</span>
        )}
      </form>
    </section>
  );
}

